import{_ as i,C as s,o as r,c as n,a4 as t,E as o}from"./chunks/framework.Y6MpCTxc.js";const b=JSON.parse('{"title":"Introduction","description":"JSVision is a TypeScript SDK for building full-screen, keyboard-and-mouse driven applications that run in a terminal — and, unchanged, in a browser.","frontmatter":{"title":"Introduction","description":"JSVision is a TypeScript SDK for building full-screen, keyboard-and-mouse driven applications that run in a terminal — and, unchanged, in a browser."},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),d={name:"guide/index.md"};function l(p,e,h,c,u,m){const a=s("PlayExample");return r(),n("div",null,[e[0]||(e[0]=t(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>JSVision is a TypeScript SDK for full-screen, event-driven applications rendered in terminal cells. Instead of printing a result and exiting, a JSVision program keeps a view tree alive, receives keyboard and mouse input, updates state, and paints new frames until the application quits.</p><p>This course gives you the map before the details. You will learn what the application owns, what the host runtime owns, run a small real application, and choose the next Guide course for your goal.</p><h2 id="who-this-course-is-for" tabindex="-1">Who this course is for <a class="header-anchor" href="#who-this-course-is-for" aria-label="Permalink to &quot;Who this course is for&quot;">​</a></h2><p>Start here if you are comfortable reading a short TypeScript program but have not built a terminal UI before. There are no JSVision prerequisites. To run the Node example locally you need Node 22 or newer, an ESM project, and an interactive terminal; the next course walks through that setup.</p><p>By the end, you should be able to:</p><ul><li>explain the difference between application code, the JSVision event loop, and a host runtime;</li><li>recognize the rendered terminal frame as output rather than application state;</li><li>run a first application and quit it cleanly; and</li><li>choose the next course without learning packages, layout, or reactivity out of order.</li></ul><h2 id="mental-model" tabindex="-1">Mental model <a class="header-anchor" href="#mental-model" aria-label="Permalink to &quot;Mental model&quot;">​</a></h2><p>Keep three responsibilities separate:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Owns</th><th>Does not own</th></tr></thead><tbody><tr><td><strong>Application</strong></td><td>Views, state, commands, focus, and the decision to quit</td><td>Reading terminal bytes or restoring terminal modes</td></tr><tr><td><strong>Host runtime</strong></td><td>Input, resize events, capability-aware terminal setup, and frame delivery</td><td>Your feature state or screen structure</td></tr><tr><td><strong>Terminal frame</strong></td><td>The cells currently visible to the user</td><td>The durable source of truth for the application</td></tr></tbody></table><p>The data moves in both directions:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>keyboard · mouse · resize</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>host runtime → event loop → application views and state</span></span>
<span class="line"><span>          ↑                         ↓</span></span>
<span class="line"><span>          └──────── rendered terminal frame</span></span></code></pre></div><p><code>createApplication()</code> assembles the application shell and event loop. On Node, <code>app.run()</code> connects that loop to the terminal host, enters the interactive screen, forwards input and resizes, and writes rendered frames. When the quit command resolves—or startup or runtime work throws—the run path restores the terminal in its cleanup path.</p><p>The live examples on this site use a browser host instead of <code>app.run()</code>. They still mount a real application and drive its real event loop; the surrounding docs helper is not part of the public API you copy into a project.</p><h2 id="your-first-jsvision-application" tabindex="-1">Your first JSVision application <a class="header-anchor" href="#your-first-jsvision-application" aria-label="Permalink to &quot;Your first JSVision application&quot;">​</a></h2><p>This is a complete application with one body view and one discoverable quit command:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Commands, Text, createApplication, statusItem, statusLine } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@jsvision/ui&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createApplication</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  content: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Hello from JSVision&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  statusLine: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">statusLine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">statusItem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;~Alt-X~ Quit&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Commands.quit, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Alt+X&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> exitCode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">process.exitCode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> exitCode;</span></span></code></pre></div><p>Important details:</p><ul><li><code>content</code> is the application body. Passing a body creates a full-screen content application; omitting it gives you the classic <code>Desktop</code> window manager.</li><li><code>statusItem()</code> makes the quit action and its key chord visible instead of hiding them in code.</li><li>The first argument is the displayed label. <code>~Alt-X~</code> marks its emphasized segment, while the third argument binds the real <strong>Alt+X</strong> chord.</li><li><code>app.run()</code> resolves with the exit code carried by the quit command. Setting <code>process.exitCode</code> lets normal JavaScript cleanup finish.</li></ul><p>Menus, windows, layouts, and reactive state are deliberately absent. They are later lessons, not requirements for a first result.</p><h2 id="run-the-application" tabindex="-1">Run the application <a class="header-anchor" href="#run-the-application" aria-label="Permalink to &quot;Run the application&quot;">​</a></h2><p>After completing <a href="/jsvision/pr-preview/pr-202/guide/install-and-packages.html">Install &amp; packages</a>, save the snippet as <code>src/main.ts</code> and run it with the TypeScript runner configured by that course:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/main.ts</span></span></code></pre></div><p>The screen should show the text body and a status line. Press <strong>Alt+X</strong> to emit the standard quit command. A successful result is not merely “text appeared”: input reached the event loop, the application produced a frame, and the host restored the terminal after the loop ended.</p><p>The laboratory below makes those boundaries visible. Press <strong>Alt+N</strong> or activate <strong>Next stage</strong> to follow one frame from application construction, through the host runtime, to the terminal. Press <strong>Alt+R</strong> to reset the explanation.</p>`,25)),o(a,{id:"guides/introduction-runtime",title:"Trace the first frame",blurb:"Advance through application, host runtime, and terminal-frame stages to see what each layer owns."}),e[1]||(e[1]=t('<h2 id="common-first-run-failures" tabindex="-1">Common first-run failures <a class="header-anchor" href="#common-first-run-failures" aria-label="Permalink to &quot;Common first-run failures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Correction</th><th>Evidence</th></tr></thead><tbody><tr><td>Node reports an unsupported module or <code>require()</code> error</td><td>The project is not using the required ESM setup</td><td>Follow the package and TypeScript configuration exactly</td><td>The public import resolves before the app starts</td></tr><tr><td>Startup reports that terminal essentials are not met</td><td>The process has no interactive TTY, such as a redirected or CI run</td><td>Run it in an interactive terminal; use a deliberate headless harness for tests</td><td>The app enters its interactive screen instead of failing before host setup</td></tr><tr><td>The process keeps running after the first frame</td><td>A full-screen app is event-driven and waits for a quit command</td><td>Keep the visible quit status item and press <strong>Alt+X</strong></td><td><code>app.run()</code> resolves and the normal shell returns</td></tr><tr><td>A browser example works but the copied program cannot import its helper</td><td>The docs shell is repository infrastructure, not consumer API</td><td>Import <code>createApplication</code> from <code>@jsvision/ui</code></td><td>TypeScript resolves only public package exports</td></tr></tbody></table><p>Do not “fix” a missing TTY by disabling the runtime check in a production entry point. The <code>requireTty: false</code> option exists for a controlled headless harness with injected input and output, not for making an unusable interactive process appear healthy.</p><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>Keep the application model host-neutral.</strong> Put feature state and commands in the application; later Node and browser hosts can drive the same model without owning it.</li><li><strong>Give every important action a visible path.</strong> A status or menu hint makes quit and recovery discoverable to keyboard users.</li><li><strong>Treat the rendered frame as evidence, not state.</strong> Tests may inspect frames, but business state belongs in signals and models so it remains explainable and reusable.</li><li><strong>Let <code>run()</code> own the terminal lifecycle.</strong> Bypassing its cleanup path risks leaving raw mode or the alternate screen active after an error.</li></ul><h2 id="choose-your-next-course" tabindex="-1">Choose your next course <a class="header-anchor" href="#choose-your-next-course" aria-label="Permalink to &quot;Choose your next course&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your goal</th><th>Continue with</th><th>Why</th></tr></thead><tbody><tr><td>Run the snippet locally or choose packages</td><td><a href="/jsvision/pr-preview/pr-202/guide/install-and-packages.html">Install &amp; packages</a></td><td>Establish Node 22+, ESM, TypeScript, and supported imports first</td></tr><tr><td>Arrange views into a responsive screen</td><td><a href="/jsvision/pr-preview/pr-202/guide/layout.html">Layout</a></td><td>Learn terminal-cell geometry and size negotiation</td></tr><tr><td>Connect changing data to the interface</td><td><a href="/jsvision/pr-preview/pr-202/guide/reactive-state.html">Reactive state</a></td><td>Learn signals, derived state, effects, and ownership</td></tr><tr><td>Use JSVision through Codex</td><td><a href="/jsvision/pr-preview/pr-202/guide/codex-plugin.html">Codex plugin</a></td><td>Install the supported integration and understand its canonical sources</td></tr></tbody></table><p>After those foundations, <a href="/jsvision/pr-preview/pr-202/guide/application-shell.html">The application shell</a> teaches menus, desktops, windows, status composition, and the complete lifecycle.</p><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ol><li>Before running the lab, predict which layer owns keyboard decoding and which owns the quit command. Advance the stages and check your answer.</li><li>Change the greeting text in the snippet. Explain why this changes application state and the resulting frame but not the host runtime.</li><li>As a reading exercise, temporarily remove the visible status item. Notice that this also removes the snippet&#39;s <strong>Alt+X</strong> binding: registering <code>Commands.quit</code> does not create an input path by itself. Restore the item before running the application.</li></ol><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><p>The Guide is a curriculum, not a symbol index. Follow it in order when you are new, or enter at a course whose prerequisites you already understand. <strong>Complete</strong> courses meet the current course and live-lab directive. If future <strong>Upgrade</strong> or <strong>Planned</strong> entries appear, they remain visible here while incomplete pages stay out of the sidebar.</p><h3 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>Stage</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/jsvision/pr-preview/pr-202/guide/">Introduction</a></td><td>Complete</td><td>Understand the product, run the live shell, and choose a learning path.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/install-and-packages.html">Install &amp; packages</a></td><td>Complete</td><td>Choose packages and configure a Node 22+ ESM project.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/codex-plugin.html">Codex plugin</a></td><td>Complete</td><td>Use the supported agent integration and canonical JSVision guidance.</td></tr></tbody></table><h3 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>Stage</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/jsvision/pr-preview/pr-202/guide/layout.html">Layout</a></td><td>Complete</td><td>Compose responsive cell layouts, overlays, and exact placement.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/reactive-state.html">Reactive state</a></td><td>Complete</td><td>Model state, derived values, bindings, effects, and lifetimes.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/views-and-focus.html">Views &amp; focus</a></td><td>Complete</td><td>Understand retained trees, mounting, invalidation, tab order, and focus restoration.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/events-commands-and-keymaps.html">Events, commands &amp; keymaps</a></td><td>Complete</td><td>Route input and design discoverable command systems.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/keyboard-and-clipboard.html">Keyboard &amp; clipboard</a></td><td>Complete</td><td>Use editing chords and authorized clipboard adapters.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/text-unicode-and-cells.html">Text, Unicode &amp; terminal cells</a></td><td>Complete</td><td>Handle graphemes, wide glyphs, wrapping, clipping, and ASCII-safe fallbacks.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/scrolling-lists-and-large-content.html">Scrolling, lists &amp; large content</a></td><td>Complete</td><td>Design viewports, selection, scrolling, and bounded rendering.</td></tr></tbody></table><h3 id="building-applications" tabindex="-1">Building applications <a class="header-anchor" href="#building-applications" aria-label="Permalink to &quot;Building applications&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>Stage</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/jsvision/pr-preview/pr-202/guide/application-shell.html">The application shell</a></td><td>Complete</td><td>Build and run menus, status, commands, desktops, and windows.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/dialogs-and-modality.html">Dialogs &amp; modality</a></td><td>Complete</td><td>Build validated, cancellable, focus-safe modal workflows.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/async-work.html">Async work, cancellation &amp; progress</a></td><td>Complete</td><td>Keep input responsive while handling progress, cancellation, cleanup, and stale results.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/forms.html">Forms</a></td><td>Complete</td><td>Build typed field state, validation, async submission, and reset.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/files-and-filesystem.html">Files &amp; the FileSystem seam</a></td><td>Complete</td><td>Run the same file workflows over native, virtual, and custom hosts.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/i18n.html">Internationalization</a></td><td>Complete</td><td>Author, load, validate, switch, format, and test locales.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/screens-and-routing.html">Screens &amp; routing</a></td><td>Complete</td><td>Build typed screen stacks with history, parameters, shared chrome, and focus.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/theming-and-colour-depth.html">Theming &amp; colour depth</a></td><td>Complete</td><td>Author semantic themes that preserve meaning as color capabilities degrade.</td></tr></tbody></table><h3 id="extending-and-integrating" tabindex="-1">Extending and integrating <a class="header-anchor" href="#extending-and-integrating" aria-label="Permalink to &quot;Extending and integrating&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>Stage</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/jsvision/pr-preview/pr-202/guide/running-in-the-browser.html">Running in the browser</a></td><td>Complete</td><td>Mount unchanged applications through the browser host and virtual seams.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/writing-your-own-widget.html">Writing your own widget</a></td><td>Complete</td><td>Implement measurement, drawing, focus, input, reactivity, and cleanup.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/testing-headlessly.html">Testing headlessly</a></td><td>Complete</td><td>Drive views, input, dialogs, resize, and failures without a real terminal.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/application-architecture.html">Application architecture &amp; best practices</a></td><td>Complete</td><td>Organize state, services, commands, screens, ownership, and feature boundaries.</td></tr></tbody></table><h3 id="specialist-courses" tabindex="-1">Specialist courses <a class="header-anchor" href="#specialist-courses" aria-label="Permalink to &quot;Specialist courses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>Stage</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/jsvision/pr-preview/pr-202/components/data-grid/">Data Grid course</a></td><td>Complete</td><td>Progress from typed sources and columns through editing, scaling, and personalization.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/components/code-editor/">Code Editor course</a></td><td>Complete</td><td>Build editor experiences from documents through languages, LSP, safety, and recovery.</td></tr></tbody></table><h3 id="operating-a-real-app" tabindex="-1">Operating a real app <a class="header-anchor" href="#operating-a-real-app" aria-label="Permalink to &quot;Operating a real app&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>Stage</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/jsvision/pr-preview/pr-202/guide/debugging.html">Debugging</a></td><td>Complete</td><td>Diagnose layout, focus, commands, rendering, capabilities, and lifecycle failures.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/crash-safety.html">Crash safety &amp; terminal restore</a></td><td>Complete</td><td>Understand restore guarantees, signals, essentials, and degradations.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/untrusted-text.html">Displaying untrusted text safely</a></td><td>Complete</td><td>Prevent terminal injection and redact sensitive diagnostics.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/accessibility.html">Accessibility &amp; resilient interaction</a></td><td>Complete</td><td>Design keyboard-complete, non-color-dependent, reduced-geometry interfaces.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/terminal-capabilities.html">Terminal capabilities &amp; portability</a></td><td>Complete</td><td>Adapt honestly across color, mouse, glyph, SSH, tmux, Windows, and browser environments.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/in-production.html">In production</a></td><td>Complete</td><td>Package, deploy, observe, support, and set evidence-based expectations.</td></tr><tr><td><a href="/jsvision/pr-preview/pr-202/guide/complete-application.html">Build a complete application</a></td><td>Complete</td><td>Apply the complete curriculum in one beginner-to-production release workflow.</td></tr></tbody></table><h2 id="where-to-next" tabindex="-1">Where to next <a class="header-anchor" href="#where-to-next" aria-label="Permalink to &quot;Where to next&quot;">​</a></h2><ul><li><strong><a href="/jsvision/pr-preview/pr-202/components/">Components</a></strong> — every widget, with a live example you can drive on each page.</li><li><strong><a href="/jsvision/pr-preview/pr-202/apps/">Apps</a></strong> — complete sample applications, running in the browser.</li><li><strong><a href="/jsvision/pr-preview/pr-202/guide/keyboard-and-clipboard.html">Keyboard &amp; clipboard</a></strong> — the selection and clipboard chords every editable widget gets for free.</li><li><strong><a href="/jsvision/pr-preview/pr-202/api/">API reference</a></strong> — the generated reference for every public symbol.</li></ul>',26))])}const v=i(d,[["render",l]]);export{b as __pageData,v as default};
